# Tidy Asset Allocation in R
# Chapter 13: Numerical Optimization and Solvers
# https://www.tidy-pm.com/dev/chapters/13-solvers.html
#
# The R code of the chapter, in the order it runs there.
# Run 00-setup.R once, then this file from the folder that holds it;
# generated by tools/build-code.py from the book's source.

## ---- setup ----
source("_common.R")
library(tidypm)
library(knitr)

## ---- data ----
R  <- as_xts_pm(sim_class_returns_monthly, date, class, return)
Re <- R - sim_riskfree_monthly$return
S  <- stats::cov(Re)
mu <- colMeans(Re)

## ---- truth ----
# ===== A problem whose answer we already know =====
N <- ncol(Re)

# The long-only tangency portfolio, solved directly:
#   min w'Sw  s.t.  mu'w = 1, w >= 0,  then rescaled to sum to one.
# No PortfolioAnalytics in the loop, so it cannot inherit any of its mistakes.
sol <- quadprog::solve.QP(Dmat = 2 * S, dvec = rep(0, N),
                          Amat = cbind(mu, diag(N)),
                          bvec = c(1, rep(0, N)), meq = 1)
w_true <- pmax(sol$solution, 0)
w_true <- setNames(w_true / sum(w_true), colnames(Re))

sharpe <- function(w) sum(mu * w) / sqrt(as.numeric(t(w) %*% S %*% w))
c(monthly_sharpe = sharpe(w_true), holdings = sum(w_true > 1e-6))

## ---- race ----
# ===== Racing them on a problem with an answer =====
spec <- portfolio.spec(assets = colnames(Re)) |>
  add.constraint(type = "full_investment") |>
  add.constraint(type = "long_only") |>
  add.objective(type = "return", name = "mean") |>
  add.objective(type = "risk",   name = "StdDev")

set.seed(1602)

run <- function(method, ...) {
  t0 <- Sys.time()
  o  <- try(suppressWarnings(
    optimize.portfolio(Re, spec, optimize_method = method,
                       maxSR = TRUE, trace = FALSE, ...)), silent = TRUE)
  secs <- as.numeric(difftime(Sys.time(), t0, units = "secs"))
  if (inherits(o, "try-error")) {
    return(tibble::tibble(solver = method, sharpe = NA_real_, share = NA_real_,
                          holdings = NA_integer_, seconds = secs))
  }
  w <- extractWeights(o)[colnames(Re)]
  w[is.na(w)] <- 0
  tibble::tibble(solver = method, sharpe = sharpe(w),
                 share = sharpe(w) / sharpe(w_true),
                 holdings = sum(w > 1e-6), seconds = secs)
}

race <- dplyr::bind_rows(
  run("ROI"),
  run("CVXR"),
  run("random"),                       # the package default, 20,000 draws
  run("DEoptim", traceDE = 0),
  run("pso"),
  run("GenSA")
)

## ---- tbl-13-race ----
# One convex problem, six solvers, one known answer. `share` is the fraction
# of the attainable Sharpe ratio the solver actually reached; time is relative
# to `ROI` on the same machine.
race <- race |> dplyr::mutate(rel_time = seconds / seconds[solver == "ROI"])
race |>
  dplyr::arrange(dplyr::desc(share)) |>
  dplyr::mutate(sharpe = sprintf("%.4f", sharpe),
                share = sprintf("%.1f%%", 100 * share),
                rel_time = sprintf("%.0fx", rel_time)) |>
  dplyr::select(solver, sharpe, share, holdings, rel_time) |>
  kable(align = "lrrrr",
        col.names = c("", "Sharpe", "share of the best", "positions", "time, relative to ROI"))

## ---- race-claims ----
# The reading of the race: the convex pair is exact, every search is short of it
# and slower by at least an order of magnitude.
convex <- race$solver %in% c("ROI", "CVXR")
srch   <- race[!convex, ]
stopifnot(all(abs(race$share[convex] - 1) < 1e-3), all(srch$share < 0.95),
          all(srch$seconds > 10 * race$seconds[race$solver == "ROI"]))
rng <- range(srch$share)

## ---- fig-13-race ----
# ===== The searches complain about the budget constraint, and the complaint is informative =====
# What each solver achieved against what it cost. The two convex solvers sit
# alone in the top-left corner; nothing buys its way out of the bottom-right.
race |>
  dplyr::mutate(family = ifelse(solver %in% c("ROI", "CVXR"),
                                "convex", "search")) |>
  ggplot2::ggplot(ggplot2::aes(rel_time, share, colour = family)) +
  ggplot2::geom_point(size = 3) +
  ggplot2::geom_text(ggplot2::aes(label = solver), hjust = -0.2, size = 2.8,
                     show.legend = FALSE) +
  ggplot2::scale_x_log10(expand = ggplot2::expansion(mult = c(0.1, 0.35))) +
  ggplot2::scale_y_continuous(labels = scales::percent, limits = c(0.4, 1.05)) +
  ggplot2::scale_colour_manual(values = unname(tidyaa_colors[c("blue", "broken")])) +
  ggplot2::labs(x = "time relative to ROI (log scale)", y = "share of the attainable Sharpe",
                colour = NULL)

## ---- poslimit ----
# ===== Which solver honors the constraint =====
# One position fewer than the unconstrained answer holds, so the limit binds.
k_lim    <- sum(w_true > 1e-6) - 1L
stopifnot(k_lim >= 1L, k_lim < sum(w_true > 1e-6))
spec_lim <- add.constraint(spec, type = "position_limit", max_pos = k_lim)

set.seed(1602)
feas <- function(method, ...) {
  o <- try(suppressWarnings(
    optimize.portfolio(Re, spec_lim, optimize_method = method,
                       maxSR = TRUE, trace = FALSE, ...)), silent = TRUE)
  if (inherits(o, "try-error")) {
    return(tibble::tibble(solver = method, holdings = NA_integer_,
                          verdict = "errors"))
  }
  w <- extractWeights(o)
  h <- sum(w > 1e-6)
  tibble::tibble(solver = method, holdings = h,
                 verdict = if (h <= k_lim) "feasible" else "VIOLATES")
}

feasible <- dplyr::bind_rows(
  feas("ROI"), feas("random"), feas("DEoptim", traceDE = 0),
  feas("pso"), feas("GenSA")
)
feasible

## ---- poslimit-claims ----
# The verdicts the text states by name.
n_viol  <- sum(feasible$verdict == "VIOLATES")
respect <- feasible$solver[feasible$verdict == "feasible"]
ignore  <- setdiff(feasible$solver[feasible$verdict == "VIOLATES"], "ROI")
stopifnot(feasible$verdict[feasible$solver == "ROI"] == "VIOLATES", n_viol == 3,
          feasible$holdings[feasible$solver == "ROI"] == sum(w_true > 1e-6),
          all(feasible$holdings[feasible$solver %in% ignore] >= N - 1))

## ---- audit ----
# ===== Auditing the answer =====
audit <- function(opt, max_pos = NULL, sum_target = 1, tol = 1e-6) {
  w <- extractWeights(opt)
  if (is.null(w) || anyNA(w)) return("no usable weights returned")
  problems <- c(
    if (abs(sum(w) - sum_target) > tol)
      sprintf("weights sum to %.4f, not %.4f", sum(w), sum_target),
    if (min(w) < -tol)
      sprintf("negative weight of %.4f under a long-only constraint", min(w)),
    if (!is.null(max_pos) && sum(w > tol) > max_pos)
      sprintf("%d positions held under a limit of %d", sum(w > tol), max_pos)
  )
  if (length(problems)) problems else "feasible"
}

audit(optimize.portfolio(Re, spec, optimize_method = "ROI", maxSR = TRUE))

## ---- combine ----
# ===== Comparing specifications as one object =====
opts <- combine.optimizations(list(
  ROI     = optimize.portfolio(Re, spec, optimize_method = "ROI", maxSR = TRUE),
  CVXR    = optimize.portfolio(Re, spec, optimize_method = "CVXR", maxSR = TRUE)
))

round(extractWeights(opts), 4)[, 1:6]

## ---- budget ----
# ===== Why the Searches Fall Short =====
set.seed(1602)
budget <- dplyr::bind_rows(
  run("random", search_size = 20000),
  run("random", search_size = 100000)
) |>
  dplyr::mutate(search_size = c(20000, 100000), .before = 1,
                rel_time = seconds / seconds[1]) |>
  dplyr::select(search_size, share, rel_time)
budget

## ---- budget-claims ----
closed <- 100 * diff(budget$share)
open   <- 100 * (1 - budget$share[2])
stopifnot(closed > 0, open > 1, budget$rel_time[2] > 1)
